mapper.insert:

	SELECT NVL(MAX(mail_no),0) + 1
	FROM mail

INSERT 
INTO mail( mail_no
		,class_id
		,mail_type
		,mail_title
		,mail_contents
		,mail_send_date
		,sender_id
		,notice_no
	)
VALUES(
		#{mailNo}
		,#{classId}
		,#{mailType}
		,#{mailTitle}
		,#{mailContents}
		,sysdate
		,#{senderId}


				, #{noticeNo}


				, 0


	)
